functions._ebEnsureExecBriefTermsLoaded:
function _ebEnsureExecBriefTermsLoaded() {
  if (window._ebTermsCache) return Promise.resolve(window._ebTermsCache);
  if (window._ebTermsCacheLoading) return window._ebTermsCacheLoading;
  var p = (window.eli && window.eli.storage && typeof window.eli.storage.getAll === "function")
    ? window.eli.storage.getAll("exec_brief_terms")
    : Promise.resolve([]);
  window._ebTermsCacheLoading = p.then(function (rows) {
    var byType = {}, generic = [];
    (rows || []).forEach(function (r) {
      if (!r || !r.id || r.id === "__meta") return;
      if (r.id === "__generic") { generic = r.terms || []; }
      else if (Array.isArray(r.terms)) { byType[r.id] = r.terms; }
    });
    window._ebTermsCache = { byType: byType, generic: generic };
    window._ebTermsCacheLoading = null;
    return window._ebTermsCache;
  }).catch(function () {
    window._ebTermsCache = { byType: {}, generic: [] };
    window._ebTermsCacheLoading = null;
    return window._ebTermsCache;
  });
  return window._ebTermsCacheLoading;
}

functions.getExecBriefTerms:
function getExecBriefTerms(type) {
  var c = window._ebTermsCache || { byType: {}, generic: [] };
  if (type && c.byType[type] && c.byType[type].length) return c.byType[type].slice();
  return (c.generic || []).slice();
}

functions.setExecBriefTerms:
function setExecBriefTerms(type, list) {
  if (!window._ebTermsCache) window._ebTermsCache = { byType: {}, generic: [] };
  window._ebTermsCache.byType[type] = (list || []).slice();
  _ebPersistExecBriefTerms();
}

functions.clearExecBriefTerms:
function clearExecBriefTerms(type) {
  if (!window._ebTermsCache || !window._ebTermsCache.byType) return;
  delete window._ebTermsCache.byType[type];
  _ebPersistExecBriefTerms();
}

functions._ebPersistExecBriefTerms:
function _ebPersistExecBriefTerms() {
  var c = window._ebTermsCache || { byType: {}, generic: [] };
  var rows = [];
  Object.keys(c.byType || {}).forEach(function (k) {
    rows.push({ id: k, terms: c.byType[k] });
  });
  if (c.generic && c.generic.length) rows.push({ id: "__generic", terms: c.generic });
  if (window.eli && window.eli.storage && typeof window.eli.storage.put === "function") {
    rows.forEach(function (r) {
      window.eli.storage.put("exec_brief_terms", r).catch(function () {});
    });
  }
}

// HTML escape — used by _ebCards / _ebEmail / _frWizard /
// showExecutiveBriefSettings. Was a v2 kernel global; v3 owns it
// here in final_review's helpers since this is the only tool that
// uses it (the v2 cross-tool footprint of `_ebEsc` was misleading —
// only Executive Brief actually references it post-v3-split).

functions._ebEsc:
function _ebEsc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// Robust JSON extractor — v2-faithful (taskpane_v2.js:13066). Keeps
// every recovery branch so AI responses with stray prose / unescaped
// newlines / numbered-list shapes still parse to a usable value.

functions._ebParseAiJson:
function _ebParseAiJson(jsonString) {
  if (!jsonString) return {};
  var clean = String(jsonString)
    .replace(/```json/g, "")
    .replace(/```/g, "")
    .replace(/^[^{[]*/, "")
    .replace(/[^}\]]*$/, "")
    .trim();
  try { return JSON.parse(clean); }
  catch (e) {
    try {
      var recovered = [];
      var rx = /\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}/g, m;
      while ((m = rx.exec(clean)) !== null) {
        try { recovered.push(JSON.parse(m[0])); } catch (e2) { /* skip */ }
      }
      if (recovered.length > 0) return recovered;
    } catch (e3) { /* fall through */ }
    try {
      var fixed = clean.replace(/(?<!["}])\n/g, "\\n");
      if (fixed.match(/^\[\w+\]/)) throw new Error("plain text list");
      return JSON.parse(fixed);
    } catch (e4) {
      if (jsonString.indexOf("1.") !== -1 || jsonString.indexOf("- ") !== -1) {
        return {
          summary: "AI returned plain text analysis.",
          changes: [{ clause: "General", change: String(jsonString).substring(0, 500), impact: "Review Manually" }],
        };
      }
      if (clean.charAt(0) === "[") return [];
      return {};
    }
  }
}

