}

functions._ebRestoreFromGenerating:
function _ebRestoreFromGenerating() {
  var oph = document.getElementById("ebOverviewPh");
  if (oph) oph.remove();
  document.querySelectorAll(".eb-card-shimmer").forEach(function (e) {
    e.remove();
  });
  var ov = document.getElementById("ebOverview");
  if (ov) ov.style.display = "";
  document.querySelectorAll("#ebCards textarea[data-eb-details]").forEach(function (ta) {
    ta.style.display = "";
  });
  document.querySelectorAll(".eb-card-generating").forEach(function (c) {
    c.classList.remove("eb-card-generating");
  });
  var btn = document.getElementById("ebRunBtn");
  if (btn) {
    if (btn.dataset.origLabel) btn.innerHTML = btn.dataset.origLabel;
    btn.disabled = false;
    btn.style.opacity = "";
    btn.style.cursor = "";
  }
}

functions._ebGetRequester:
function _ebGetRequester() {
  var sel = document.getElementById("ebReqSel");
  if (!sel) return window._ebRequester || { name: "Requester", email: "" };
  if (sel.value === "__manual__") {
    return {
      name: (document.getElementById("ebReqName") || {}).value || "Requester",
      email: (document.getElementById("ebReqEmail") || {}).value || "",
    };
  }
  var found = (window._ebSavedReqs || []).find(function (r) {
    return String(r.id) === String(sel.value);
  });
  return found || { name: "Requester", email: "" };
}

functions._ebAutoGrow:
function _ebAutoGrow(el) {
  if (!el) return;
  el.style.height = "auto";
  el.style.height = el.scrollHeight + 2 + "px";
}

functions._ebToBold:
function _ebToBold(s) {
  return String(s)
    .replace(/[A-Z]/g, function (c) {
      return String.fromCodePoint(0x1d400 + (c.charCodeAt(0) - 0x41));
    })
    .replace(/[a-z]/g, function (c) {
      return String.fromCodePoint(0x1d41a + (c.charCodeAt(0) - 0x61));
    })
    .replace(/[0-9]/g, function (c) {
      return String.fromCodePoint(0x1d7ce + (c.charCodeAt(0) - 0x30));
    });
}

functions._ebExtractCpRef:
function _ebExtractCpRef(callback) {
  if (window._ebData && typeof window._ebData.cpRef === "string") {
    callback(window._ebData.cpRef);
    return;
  }
  try {
    Word.run(function (context) {
      var body = context.document.body;
      body.load("text");
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        var footerLoads = [];
        sections.items.forEach(function (sec) {
          ["Primary", "FirstPage", "EvenPages"].forEach(function (kind) {
            try {
              var f = sec.getFooter(kind);
              f.load("text");
              footerLoads.push(f);
            } catch (e) { }
          });
        });
        return context.sync().then(function () {
          var refRegex = /CP\s*Ref(?:erence)?\s*[:#]?\s*([A-Za-z]?-?\s*[A-Za-z0-9][A-Za-z0-9\-_/]*)/i;
          // Match full multi-segment refs like "A-2026-9333-OC".
          // The previous `\b(A-\d{3,})\b` truncated at the word
          // boundary between the first digit group and the next hyphen
          // → returned "A-2026" instead of the full code.
          var altRegex = /\b(A-\d{3,}(?:-[A-Za-z0-9]+)*)\b/;
          var sources = [body.text || ""];
          footerLoads.forEach(function (f) {
            try {
              sources.push(f.text || "");
            } catch (e) { }
          });
          var found = "";
          for (var i = 0; i < sources.length && !found; i++) {
            var m = sources[i].match(refRegex);
            if (m && m[1]) {
              found = m[1].replace(/\s+/g, "").trim();
              break;
            }
            var m2 = sources[i].match(altRegex);
            if (m2 && m2[1]) {
              found = m2[1].trim();
              break;
            }
          }
          if (window._ebData) window._ebData.cpRef = found;
          callback(found);
        });
      });
    }).catch(function () {
      callback("");
    });
  } catch (e) {
    callback("");
  }
}

functions.getAcceptedDraftText:
function getAcceptedDraftText(context, maxChars) {
  var ooxmlResult = context.document.body.getOoxml();
  return context.sync().then(function () {
    var raw = ooxmlResult.value || "";
    raw = raw.replace(/<w:del\b[^>]*>[\s\S]*?<\/w:del>/g, "");
    raw = raw.replace(/<w:del\b[^>]*\/>/g, "");
    raw = raw.replace(/<w:moveFrom\b[^>]*>[\s\S]*?<\/w:moveFrom>/g, "");
    raw = raw.replace(/<w:ins\b[^>]*>([\s\S]*?)<\/w:ins>/g, "$1");
    raw = raw.replace(/<w:moveTo\b[^>]*>([\s\S]*?)<\/w:moveTo>/g, "$1");
    var matches = raw.match(/<w:t[^>]*>([\s\S]*?)<\/w:t>/g) || [];
    var text = matches
      .map(function (m) {
        return m.replace(/<[^>]+>/g, "");
      })
      .join(" ")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/\s+/g, " ")
      .trim();
    if (maxChars && text.length > maxChars) text = text.substring(0, maxChars);
    return text;
  });
}

functions.runExecutiveBrief:
function runExecutiveBrief() {
  showToast("⏳ Running final audit generation...");
  var typeSel = document.getElementById("ebTypeSel");
  var type = typeSel ? typeSel.value : window._ebType;
  if (!type) return;
  var existing = window._ebData || _ebBuildEmptyData(type);
  // Defensive — _ebBuildEmptyData always returns the right shape, but
  // window._ebData might be set elsewhere with a partial object.
  if (!existing || typeof existing !== "object") existing = { overview: "", commitments: [] };
  if (!Array.isArray(existing.commitments)) existing.commitments = [];
  var keyTerms = existing.commitments.map(function (c) {
    return c && c.title;
  }).filter(Boolean);
  if (!keyTerms.length) keyTerms = getExecBriefTerms(type) || [];
  _ebShowGenerating();

  var templatePromise = Promise.resolve(null);
  if (keyTerms.indexOf("Major Deviations from Standard Agreement") > -1) {
    // 2026-05-13 follow-up: was matching ONLY on template.type with a
    // hardcoded NDA/MTA fallback. Misses templates that store the
    // canonical `agreementType` field (build_draft, admin_template_studio,
    // and review_redlines all write THAT field, not `type`) — so the
    // "Major Deviations" prompt slot got `templateBlock = ""` and the AI
    // wrote "Not addressed in this agreement" for every doc. Now matches
    // on BOTH fields + uses the agreement_types alias catalog for
    // NDA ↔ Non-Disclosure Agreement / MTA ↔ Material Transfer
    // Agreement / Service ↔ Services Agreement style resolution.
    // Identical pattern to legal_review's `_matchesAgreementType`
    // (tools/legal_review/init.js:90-116).
    function _matchesAgreementType(catalog, templateType, docType) {
      if (!templateType || !docType) return false;
      var a = String(templateType).trim().toLowerCase();
      var b = String(docType).trim().toLowerCase();
      if (a === b) return true;
      if (a.indexOf(b) !== -1 || b.indexOf(a) !== -1) return true;
      if (!Array.isArray(catalog) || !catalog.length) return false;
      function groupFor(val) {
        for (var i = 0; i < catalog.length; i++) {
          var cat = catalog[i];
          var lbl = String(cat.label || "").toLowerCase();
          var aliases = (cat.aliases || []).map(function (x) { return String(x).toLowerCase(); });
          if (lbl === val) return aliases.concat([lbl]);
          for (var j = 0; j < aliases.length; j++) {
            if (val.indexOf(aliases[j]) !== -1 || aliases[j].indexOf(val) !== -1) {
              return aliases.concat([lbl]);
            }
          }
        }
        return null;
      }
      var gA = groupFor(a), gB = groupFor(b);
      if (gA && gB && gA[gA.length - 1] === gB[gB.length - 1]) return true;
      if (gA) for (var k = 0; k < gA.length; k++) { if (b.indexOf(gA[k]) !== -1 || gA[k].indexOf(b) !== -1) return true; }
      if (gB) for (var k2 = 0; k2 < gB.length; k2++) { if (a.indexOf(gB[k2]) !== -1 || gB[k2].indexOf(a) !== -1) return true; }
      return false;
    }
    var _templatesP = window.eli.storage.getAll(STORE_TEMPLATES)
      .then(function (rows) {
        return (rows || []).filter(function (r) {
          return r && typeof r === "object" && (!r.id || String(r.id).charAt(0) !== "_");
        });
      })
      .catch(function () { return []; });
    var _catalogP = window.eli.storage.getAll("agreement_types")
      .then(function (rows) {
        return (rows || []).filter(function (r) {
          return r && r.id && String(r.id).charAt(0) !== "_";
        });
      })
      .catch(function () { return []; });
    templatePromise = Promise.all([_templatesP, _catalogP]).then(function (r) {
      var templates = r[0] || [];
      var catalog = r[1] || [];
      var match = null;
      // Prefer templates that match via agreementType (the canonical
      // field across the codebase). Fall back to legacy `type` if
      // that's all the row has. Catalog-driven alias resolution at
      // each step.
      for (var i = 0; i < templates.length; i++) {
        var tt = templates[i].agreementType || templates[i].type || "";
        if (tt && _matchesAgreementType(catalog, tt, type)) {
          match = templates[i];
          break;
        }
      }
      // Last-resort: substring match on template `name` against the
      // agreement type's catalog aliases — catches old templates that
      // never got an agreementType field set.
      if (!match && catalog.length) {
        var typeAliases = [];
        for (var ci = 0; ci < catalog.length; ci++) {
          var c = catalog[ci];
          if (String(c.label || "").toLowerCase() === String(type).toLowerCase()) {
            typeAliases = (c.aliases || []).concat([c.label]);
            break;
          }
        }
        for (var j = 0; j < templates.length && !match; j++) {
          var nm = String(templates[j].name || "").toLowerCase();
          for (var ai = 0; ai < typeAliases.length && !match; ai++) {
            if (nm.indexOf(String(typeAliases[ai]).toLowerCase()) !== -1) {
              match = templates[j];
            }
          }
        }
      }
      // Diagnostics — when the AI emits "Not addressed" for Major
      // Deviations despite a template existing, this event log tells
      // us whether the lookup missed.
      try {
        if (window.eli && window.eli.log) {
          window.eli.log.event("tool", "final_review_template_match", {
            type: type,
            templateCount: templates.length,
            catalogCount: catalog.length,
            matched: !!match,
            matchedName: match && (match.name || match.id) || null,
            matchedField: match
              ? (match.agreementType ? "agreementType" : (match.type ? "type" : "name"))
              : null,
            contentLen: match ? String(match.content || "").length : 0,
          });
        }
      } catch (_) {}
      return match;
    }).catch(function () { return null; });
  }

  // 2026-05-13 audit fix: structural split so Word.run no longer holds
  // an open context across the 5-30s AI call. Word.run reads the doc
  // text → context closes → AI fires outside → render happens after.
  // Eliminates the proxy-invalidation crash mode flagged by audit
  // Section 1 #3 (Word.run ≤ 100ms budget violation).
  templatePromise.then(function (templateData) {
    Word.run(function (context) {
      return getAcceptedDraftText(context, 100000);
    }).then(function (docText) {
      var keyTermsList = keyTerms.map(function (t, i) { return i + 1 + ". " + t; }).join("\n");
      // 2026-05-13 follow-up: name the matched template explicitly in
      // the block so the AI knows WHICH standard it's comparing against
      // — earlier prompts dropped the file name and the AI sometimes
      // hedged ("the standard agreement, if applicable, ..."). Now the
      // block is unambiguous: "STANDARD TEMPLATE (<name>):" then the body.
      var templateBlock = "";
      if (templateData && templateData.content) {
        var _tplName = templateData.name || templateData.label || templateData.id || "matched template";
        var _tplType = templateData.agreementType || templateData.type || "";
        templateBlock =
          "STANDARD TEMPLATE (" + _tplName +
          (_tplType ? " · " + _tplType : "") + "):\n" +
          templateData.content + "\n\n";
      }
      var prompt = formatPrompt("execBriefSummary", {
        type: type,
        keyTermsList: keyTermsList,
        templateBlock: templateBlock,
        docText: docText,
      }, "You are a Senior Legal Liaison at Colgate-Palmolive. Read the agreement excerpt below and produce a factual executive brief for the business requester to approve before execution.\n\nAGREEMENT TYPE: {{type}}\n\nREQUIRED OUTPUT (raw JSON only, no markdown):\n{\n  \"overview\": \"2-3 sentence factual summary of what this agreement does and the parties involved.\",\n  \"commitments\": [\n    { \"title\": \"<exact key term title>\", \"details\": \"2-4 sentence factual summary of both parties' obligations under this term.\", \"ref\": \"<section/clause reference, e.g. 'Sec 5.2' or 'Ex A' or — if not specified>\", \"quote\": \"<8-20 word VERBATIM excerpt copied EXACTLY from the document that anchors this clause, used by a search function to locate it; empty string if not addressed>\", \"severity\": \"Success | Medium | Low\" }\n  ]\n}\n\nKEY TERMS TO COVER (one commitment per term in this exact order):\n{{keyTermsList}}\n\nRULES:\n- Be matter-of-fact. No legal analysis, no recommendations — just clearly explain what each party committed to.\n- If a key term is not addressed in the document, set details to 'Not addressed in this agreement.', ref to —, and quote to ''.\n- 'severity' is contextual: Success = favorable/standard, Medium = noteworthy, Low = minor administrative.\n- Use the EXACT title text given.\n- 'details' MUST be substantive (3+ full sentences) covering scope, each party's obligations, and any thresholds, dates, or exceptions. The 'quote' field is separate metadata and does NOT replace, summarize, or shorten any detail content.\n- 'quote' MUST be a contiguous verbatim excerpt copied character-for-character from the document — no paraphrasing, no quote marks added — so it can be located by a literal search.\n- DEFAULT-RULE INTERPRETATIONS — when a term is silent, explain what the silence means in practice:\n    • 'Major Deviations from Standard Agreement': This entry MUST be a clause-by-clause comparison between the DOCUMENT EXCERPT and the STANDARD TEMPLATE block below — the template is the canonical Colgate-Palmolive form for this agreement type. When STANDARD TEMPLATE (... ): IS present below, you MUST produce real deviation findings — never 'Not addressed in this agreement.' for this term. Walk the template's clauses in order, find their counterparts in the DOCUMENT EXCERPT, and list every substantive textual or substantive-meaning difference (different cap, different term length, missing carve-out, added obligation, swapped governing law, etc.). State each difference strictly factually — no subjective words like 'notable', 'restrictive', 'unreasonable', or 'concerning'. Completely ignore (a) changes to text originally enclosed in brackets (party names, dates, specific purpose fields), (b) pure formatting/numbering changes, and (c) immaterial wording polish. If — and only if — NO STANDARD TEMPLATE block appears below, set details to 'No standard template installed for this agreement type — install one via Build Draft → Templates to enable deviation analysis.', ref to —, quote to ''.\n    • 'Conflicts of Interest' / 'Non-Solicit / Conflicts': if the agreement does NOT restrict the third party from working with others on related subject matter, set details to: 'Not addressed in this agreement. By default, the third party is free to work for other parties (including competitors) on related subject matter during the term of this agreement.' Set ref to — and quote to ''.\n    • 'Publication Control' / 'Publication Rights': if silent, default rule is the third party may publish freely; explain that.\n    • 'IP Ownership of Results' / 'IP & Deliverables': if silent, default rule is each party owns what it creates; explain that.\n    • 'Confidentiality Duration': if silent, default rule is no time limit on confidentiality obligations; explain that.\n\n{{templateBlock}}DOCUMENT EXCERPT:\n{{docText}}");
      return window.eli.ai.completeJSON(prompt, null, { jsonMode: true });
    }).then(function (aiData) {
      // eli.ai.completeJSON returns the already-parsed object —
      // don't wrap it in _ebParseAiJson (would no-op on objects and
      // crash on the indexOf fallback if completeJSON ever degrades
      // to a string-y response).
      aiData = aiData || {};
      if (!Array.isArray(aiData.commitments)) aiData.commitments = [];
      var aiByTitle = {};
      aiData.commitments.forEach(function (c) {
        if (c && c.title) aiByTitle[String(c.title).toLowerCase().trim()] = c;
      });
      var merged = {
        overview: aiData.overview || existing.overview || "",
        commitments: existing.commitments.map(function (orig) {
          var match = aiByTitle[String(orig.title).toLowerCase().trim()];
          return {
            title: orig.title,
            details: (match && match.details) || orig.details || "",
            ref: (match && match.ref) || orig.ref || "—",
            quote: (match && match.quote) || orig.quote || "",
            severity: (match && match.severity) || orig.severity || "Low",
            included: orig.included !== false,
          };
        }),
      };
      renderExecutiveBriefResults(merged, type, false);
      try {
        if (window.eli && window.eli.activity && window.eli.activity.add) {
          var _ebIncluded = (merged.commitments || []).filter(function (c) {
            return c.included !== false;
          }).length;
          // 2026-05-13 follow-up: restoreChannel + restoreKey added so
          // the activity feed item is restorable — the registered
          // `activity_restore.approval-brief` handler in init.js
          // rehydrates window._ebData + window._ebType and jumps the
          // wizard to step 2 (Final Audit) so the brief reappears as
          // it was when the user last left it. Without these the entry
          // showed up in the feed but the kernel's _appendItem gated
          // restorability on (payload && restoreChannel && restoreKey)
          // — missing fields = no click handler = dead link.
          window.eli.activity.add({
            type: "approval-brief",
            icon: "💼",
            label: "Final Review",
            summary: type + " — " + _ebIncluded + " review item" + (_ebIncluded === 1 ? "" : "s"),
            payload: { data: merged, type: type },
            restoreChannel: "activity_restore",
            restoreKey: "approval-brief",
          });
        }
      } catch (_) { }
    }).catch(function (e) {
      _ebRestoreFromGenerating();
      showToast("⚠️ Brief failed: " + (e.message || e));
    });
  });
}

functions.renderExecutiveBriefResults:
function renderExecutiveBriefResults(data, type, isEmpty) {
  // This function is no longer called in the new flow to render the full UI.
  // However, it is called when runExecutiveBrief() finishes to render the updated data!
  _ebRestoreFromGenerating();
  window._ebData = data;
  window._ebType = type;

  // Auto-grow textareas
  var ov = document.getElementById("ebOverview");
  if (ov) {
    ov.value = window._ebData.overview || "";
    _ebAutoGrow(ov);
  }

  ebRenderCards(false);
}

functions.ebUpdateCount:
function ebUpdateCount() {
  var el = document.getElementById("ebCount");
  if (el && window._ebData)
    el.textContent = window._ebData.commitments.filter(function (c) {
      return c.included;
    }).length;
}

functions.ebAddPoint:
function ebAddPoint() {
  if (!window._ebData) {
    showToast("⚠️ Open the Final Review tool first.");
    return;
  }
  var overlay = document.createElement("div");
  overlay.className = "eli-overlay eb-add-overlay";
  var dialog = document.createElement("div");
  dialog.className = "eli-dialog info slide-in";
  dialog.style.cssText = "width: min(92vw, 520px); max-width: 92vw; max-height: 90vh; padding: 18px; resize: both; overflow: auto; display: flex; flex-direction: column;";
  dialog.innerHTML =
    '<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">' +
    '<div class="eli-dialog-title" style="margin:0;">✨ Add a Key Term</div>' +
    '<button type="button" data-eb-add-close style="background:transparent; border:none; font-size:20px; cursor:pointer; color:#64748b; padding:0 6px;">×</button>' +
    "</div>" +
    '<div style="font-size:11px; color:#64748b; margin-bottom:12px; text-align:left; line-height:1.5;">Ask ELI to scan the document for an additional point, or add a blank card to fill in manually.</div>' +
    '<div style="font-size:9px; font-weight:800; color:#1565c0; text-transform:uppercase; letter-spacing:1px; margin-bottom:4px; text-align:left;">✨ Ask ELI to Scan Agreement</div>' +
    '<textarea id="ebAddQuery" placeholder="e.g. Are there any travel reimbursement caps? &#10;or&#10;What are the renewal terms?" style="width:100%; min-height:90px; padding:10px; font-size:12px; border:1.5px solid #cbd5e1; border-radius:6px; font-family:\'Inter\', system-ui, sans-serif; box-sizing:border-box; resize:vertical; outline:none; line-height:1.5;"></textarea>' +
    '<div style="display:flex; gap:8px; margin-top:10px;">' +
    '<button type="button" data-eb-add-ask class="btn-platinum-config primary" style="flex:1; padding:10px; font-weight:800;">✨ Ask ELI</button>' +
    "</div>" +
    '<div style="display:flex; align-items:center; gap:10px; margin:14px 0;">' +
    '<hr style="flex:1; border:none; border-top:1px solid #e2e8f0;">' +
    '<span style="font-size:9px; font-weight:800; color:#cbd5e1; letter-spacing:1px;">OR</span>' +
    '<hr style="flex:1; border:none; border-top:1px solid #e2e8f0;">' +
    "</div>" +
    '<button type="button" data-eb-add-blank class="btn-platinum-config" style="width:100%; padding:10px; font-weight:800;">➕ Add Blank Card</button>' +
    '<div id="ebAddStatus" style="font-size:11px; color:#64748b; margin-top:10px; text-align:center; min-height:14px;"></div>';
  overlay.appendChild(dialog);
  document.body.appendChild(overlay);
  function closeAdd() {
    overlay.remove();
  }
  function setBusy(busy, msg) {
    var ask = dialog.querySelector("[data-eb-add-ask]");
    var blank = dialog.querySelector("[data-eb-add-blank]");
    var status = dialog.querySelector("#ebAddStatus");
    if (ask) ask.disabled = busy;
    if (blank) blank.disabled = busy;
    if (status) status.textContent = msg || "";
  }
  function pushCommitment(c) {
    window._ebData.commitments.push({
      title: c.title || "New Key Term",
      details: c.details || "",
      ref: c.ref || "Manual",
      quote: c.quote || "",
      severity: c.severity || "Low",
      included: true,
    });
    ebRenderCards();
    ebUpdateCount();
  }
  dialog.querySelector("[data-eb-add-close]").onclick = closeAdd;
  dialog.querySelector("[data-eb-add-blank]").onclick = function () {
    pushCommitment({
      title: "New Key Term",
      details: "Factual summary of both parties' obligations...",
      ref: "Manual",
    });
    closeAdd();
  };
  dialog.querySelector("[data-eb-add-ask]").onclick = function () {
    var query = (dialog.querySelector("#ebAddQuery") || {}).value || "";
    query = String(query).trim();
    if (!query) {
      showToast("⚠️ Enter a question for ELI first.");
      return;
    }
    setBusy(true, "🔍 Scanning document...");
    var type = window._ebType || "Agreement";
    // 2026-05-13 audit fix: structural split so Word.run closes before
    // the AI call. Word reads doc text → context closes → AI fires
    // outside → push commitment when done. Removes Word.run ≤ 100ms
    // budget violation + proxy-invalidation risk during the AI wait.
    Word.run(function (context) {
      var body = context.document.body;
      body.load("text");
      return context.sync().then(function () {
        return (body.text || "").substring(0, 100000);
      });
    }).then(function (docText) {
      var prompt = formatPrompt("execBriefKeyTerm", {
        type: type,
        query: query,
        docText: docText,
      }, "You are a Senior Legal Liaison at Colgate-Palmolive. Read the agreement excerpt below and answer the requester's question with a single, factual key term entry.\n\nAGREEMENT TYPE: {{type}}\nREQUESTER QUESTION: {{query}}\n\nRETURN RAW JSON (no markdown):\n{ \"title\": \"<concise key term name, max 5 words>\", \"details\": \"<2-4 sentence factual summary of both parties' obligations on this point>\", \"ref\": \"<section/clause reference like 'Sec 5.2' or 'Ex A' or '—' if not specified>\", \"quote\": \"<8-20 word VERBATIM excerpt copied EXACTLY from the document that anchors this clause; empty string if not addressed>\", \"severity\": \"Success | Medium | Low\" }\n\nRULES:\n- Be matter-of-fact. Just say what each party committed to.\n- If the document does not address the question, set details to 'Not addressed in this agreement.', ref to —, and quote to ''.\n- 'severity' is contextual: Success = favorable/standard, Medium = noteworthy, Low = minor administrative.\n- 'quote' MUST be a contiguous verbatim excerpt copied character-for-character from the document so it can be located by literal search.\n\nDOCUMENT EXCERPT:\n{{docText}}");
      return window.eli.ai.completeJSON(prompt, null, { jsonMode: true });
    }).then(function (c) {
      // eli.ai.completeJSON returns the parsed object directly.
      c = c || {};
      if (!c.title) c.title = query.length > 30 ? query.substring(0, 27) + "..." : query;
      pushCommitment(c);
      showToast("✅ Added: " + c.title);
      closeAdd();
    }).catch(function (e) {
      setBusy(false, "");
      showToast("⚠️ Scan failed: " + (e.message || e));
    });
  };
  setTimeout(function () {
    var q = dialog.querySelector("#ebAddQuery");
    if (q) q.focus();
  }, 50);
}

functions._ebShowEmailDialog:
function _ebShowEmailDialog(cpRef) {
  if (!window._ebData) return;
  var requester = _ebGetRequester();
