  var dialog = document.createElement("div");
  dialog.className = "eli-dialog info slide-in";
  dialog.style.cssText = "width: min(92vw, 720px); max-width: 92vw; max-height: 90vh; padding: 16px; resize: both; overflow: auto; display: flex; flex-direction: column;";
  // X button uses the kernel's standard .eli-dialog-close class which
