      } catch (e) {
        if (navigator.clipboard.writeText) {
          navigator.clipboard.writeText(clipText).then(done).catch(fallbackPlain);
        } else {
          fallbackPlain();
        }
      }
    } else if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(clipText).then(done).catch(fallbackPlain);
    } else {
      fallbackPlain();
