functions.ebLocate:
function ebLocate(idx, btn) {
  if (!window._ebData || !window._ebData.commitments[idx]) return;
  var item = window._ebData.commitments[idx];

  // Normalize cosmetic glyph drift that breaks Word's exact match.
  // AI sources (Gemini/Claude/etc.) often "fix" punctuation when
  // copying — smart quotes for straight, en/em dash for hyphen, NBSP
  // between numbers and units, ellipsis char instead of "...". Word's
  // body.search treats these as literal different characters.
  function _normalize(s) {
    return String(s || "")
      .replace(/[‘’‚‛′]/g, "'")  // smart single → '
      .replace(/[“”„‟″]/g, '"')  // smart double → "
      .replace(/[–—−]/g, "-")              // en/em/minus → hyphen
      .replace(/ /g, " ")                              // NBSP → space
      .replace(/…/g, "...")                            // ellipsis → ...
      .replace(/[\r\n\t]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }
  function _clean(s) {
    return _normalize(s).slice(0, 220);
  }
  function _headAt(s, max) {
    if (!s) return "";
    if (s.length <= max) return s;
    var cut = s.slice(0, max);
    var lastSpace = cut.lastIndexOf(" ");
    if (lastSpace > max * 0.6) cut = cut.slice(0, lastSpace);
    return cut.trim();
  }

  // Build candidates in priority order. De-dup as we go.
  var candidates = [];
  var seen = {};
  function _add(s) {
    var n = _clean(s);
    if (n && n.length >= 6 && !seen[n]) {
      seen[n] = true;
      candidates.push(n);
    }
  }
  _add(item.quote);
  _add(_headAt(_clean(item.quote), 120));
  _add(_headAt(_clean(item.quote), 60));
  if (item.ref && item.ref !== "—" && item.ref !== "Manual") {
    var ref = _clean(item.ref);
    // Refs can be short ("§5.2") — let those through with a lower floor.
    if (ref && ref.length >= 2 && !seen[ref]) {
      seen[ref] = true;
      candidates.push(ref);
    }
  }
  if (item.details) {
    var first = String(item.details).split(/(?<=[.!?])\s+/)[0] || "";
    _add(_headAt(_clean(first), 120));
  }

  if (!candidates.length) {
    if (typeof showToast === "function") showToast("⚠️ No anchor text — regenerate the brief or add a quote.");
    return;
  }

  // v2 back-compat — kept first so any monkey-patched window.locateText
  // still gets a shot. Only the first (best) candidate goes through.
  if (typeof window.locateText === "function") {
    try { window.locateText(candidates[0], btn, true); return; } catch (e) { /* fall through */ }
  }
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    if (typeof showToast === "function") showToast("⚠️ Locate unavailable — Word host not ready.");
    return;
  }

  // Brief visual hint that locate is in flight.
  var origLabel = btn && btn.innerHTML;
  var restored = false;
  function _restoreBtn() {
    if (restored) return;
    restored = true;
    if (btn) { btn.disabled = false; btn.innerHTML = origLabel; }
  }
  if (btn) { btn.disabled = true; btn.innerHTML = "…"; }

  // Hard timeout — Word.run CAN hang in certain edge cases (search
  // pattern with unbalanced wildcards, doc with stale proxy, etc.).
  // Race the locate against a 6s timer so the button always restores
  // and the user gets actionable feedback instead of a dead UI.
  var TIMEOUT_MS = 6000;
  var timedOut = false;
  var timer = setTimeout(function () {
    timedOut = true;
    _restoreBtn();
    if (typeof showToast === "function") {
      showToast("⚠️ Locate timed out (>" + (TIMEOUT_MS / 1000) + "s). Try regenerating the brief or use the doc's Find.", "warn");
    }
  }, TIMEOUT_MS);

  // Run one body.search call wrapped in its own load+sync. Returns
  // Promise<Word.Range | null>. Swallows search-side throws (some
  // patterns trigger Word.GeneralException) so the caller can move on
  // to the next candidate / option.
  function _runOne(context, needle, opts) {
    return new Promise(function (resolve) {
      try {
        var r = context.document.body.search(needle, opts);
        r.load("items");
        context.sync().then(function () {
          resolve(r.items && r.items.length ? r.items[0] : null);
        }).catch(function () { resolve(null); });
      } catch (e) {
        resolve(null);
      }
    });
  }

  // Per candidate, two option sets: strict (exact) and forgiving
  // (ignorePunct + ignoreSpace). matchWildcards stays OFF — wildcard
  // search has too many sharp edges (parens / brackets / asterisks in
  // the quote silently break it).
  var OPTION_SETS = [
    { matchCase: false },
    { matchCase: false, ignorePunct: true, ignoreSpace: true },
  ];

  function _searchAllCandidates(context) {
    // Sequential reduce — each candidate × each option set, short
    // circuit when a match is found. Always resolves (never rejects).
    return candidates.reduce(function (chain, needle) {
      return chain.then(function (range) {
        if (range || timedOut) return range;
        return OPTION_SETS.reduce(function (innerChain, opts) {
          return innerChain.then(function (inner) {
            if (inner || timedOut) return inner;
            return _runOne(context, needle, opts);
          });
        }, Promise.resolve(null));
      });
    }, Promise.resolve(null));
  }

  window.eli.host.runRaw("final_review:locate", function (context) {
    return _searchAllCandidates(context).then(function (range) {
      if (!range || timedOut) return false;
      try { range.select(); range.scrollIntoView(); } catch (e) { /* tolerate */ }
      return context.sync()
        .then(function () { return true; })
        .catch(function () { return true; });  // select likely landed; ignore post-select sync errors
    });
  }).then(function (found) {
    clearTimeout(timer);
    if (timedOut) return;  // timeout already restored + toasted
    _restoreBtn();
    if (!found && typeof showToast === "function") {
      showToast("⚠️ Couldn't find that clause in the doc.", "warn");
    }
    try {
      if (window.eli && window.eli.log) {
        window.eli.log.event("tool", "final_review_locate", {
          found: !!found,
          candidateCount: candidates.length,
        });
      }
    } catch (_) {}
  }).catch(function (err) {
    clearTimeout(timer);
    if (timedOut) return;
    _restoreBtn();
    if (typeof showToast === "function") {
      showToast("⚠️ Locate failed: " + (err && err.message || "unknown"), "err");
    }
  });
}

