function showExecutiveBriefSettings() {
  var types = getAgreementTypes();
  var optHtml = types
    .map(function (t) {
      return '<option value="' + _ebEsc(t) + '">' + _ebEsc(t) + "</option>";
    })
    .join("");
  var overlay = document.createElement("div");
  overlay.className = "eli-overlay eb-settings-overlay";
  var dialog = document.createElement("div");
  dialog.className = "eli-dialog info slide-in";
  dialog.style.cssText = "width: min(92vw, 560px); max-width: 92vw; max-height: 90vh; padding: 18px; resize: both; overflow: auto; display: flex; flex-direction: column; position: relative;";
  dialog.innerHTML =
    '<button type="button" data-ebs-close aria-label="Close" ' +
      'style="position:absolute; top:10px; right:12px; background:transparent; border:none; font-size:22px; line-height:1; cursor:pointer; color:#64748b; padding:2px 8px; border-radius:4px; transition:background .12s ease, color .12s ease;" ' +
      'onmouseover="this.style.background=\'#f1f5f9\'; this.style.color=\'#0f172a\';" ' +
      'onmouseout="this.style.background=\'transparent\'; this.style.color=\'#64748b\';"' +
    '>×</button>' +
    '<div class="eli-dialog-title" style="margin:0 32px 0 0;">⚙️ Final Review Settings</div>' +
    '<div style="font-size:12px; color:#475569; margin-bottom:10px; text-align:left;">Edit the key terms ELI summarizes for each agreement type. One term per line.</div>' +
    '<select id="ebsType" style="width:100%; padding:8px; font-size:12px; border:1px solid #cbd5e1; border-radius:4px; margin-bottom:8px; box-sizing:border-box;">' +
    optHtml +
    "</select>" +
    '<textarea id="ebsTerms" style="width:100%; min-height:220px; flex:1; padding:8px; font-size:12px; border:1px solid #cbd5e1; border-radius:4px; font-family:\'Inter\', system-ui, sans-serif; box-sizing:border-box; resize:vertical;"></textarea>' +
    '<div style="margin-top:8px; margin-bottom:8px; padding:10px; background:#f8fafc; border:1px solid #e2e8f0; border-radius:4px; display:flex; align-items:center; gap:8px;">' +
    '<input type="checkbox" id="ebsCompareTemplate" style="transform:scale(1.15); cursor:pointer;">' +
    '<label for="ebsCompareTemplate" style="font-size:12px; font-weight:700; color:#1e293b; cursor:pointer;">Flag Major Deviations from Standard Template (if available)</label>' +
    "</div>" +
    '<div style="font-size:10px; color:#94a3b8; margin-top:2px; text-align:left;">Leave the textarea blank and click Save to fall back to defaults.</div>' +
    '<div class="eli-dialog-actions" style="margin-top:12px; flex-shrink:0;">' +
    '<button type="button" data-ebs-reset class="btn-action" style="flex:1;">↩️ Reset This Type</button>' +
    '<button type="button" data-ebs-save class="btn-action" style="flex:1; font-weight:bold;">💾 Save</button>' +
    '<button type="button" data-ebs-cancel class="btn-action" style="flex:1;">Cancel</button>' +
    "</div>";
  overlay.appendChild(dialog);
  document.body.appendChild(overlay);
  var sel = dialog.querySelector("#ebsType");
  var area = dialog.querySelector("#ebsTerms");
  var cb = dialog.querySelector("#ebsCompareTemplate");
  function loadType() {
    var terms = getExecBriefTerms(sel.value);
    var devIdx = terms.indexOf("Major Deviations from Standard Agreement");
    if (devIdx > -1) {
      cb.checked = true;
      terms.splice(devIdx, 1);
    } else {
      cb.checked = false;
    }
    area.value = terms.join("\n");
  }
  sel.onchange = loadType;
  loadType();
  function closeDialog() {
    overlay.remove();
  }
  dialog.querySelector("[data-ebs-close]").onclick = closeDialog;
  dialog.querySelector("[data-ebs-cancel]").onclick = closeDialog;
  dialog.querySelector("[data-ebs-reset]").onclick = function () {
    clearExecBriefTerms(sel.value);
    loadType();
    showToast("↩️ Cleared " + sel.value + " — re-import master JSON to restore shipped defaults");
  };
  dialog.querySelector("[data-ebs-save]").onclick = function () {
    var terms = area.value
      .split("\n")
      .map(function (s) {
        return s.trim();
      })
      .filter(function (s) {
        return !!s;
      });

    var isDefaultsOnly = terms.length === 0;

    if (cb.checked) {
      if (terms.indexOf("Major Deviations from Standard Agreement") === -1) {
        terms.push("Major Deviations from Standard Agreement");
      }
    }

    if (isDefaultsOnly && !cb.checked) {
      clearExecBriefTerms(sel.value);
      showToast("↩️ " + sel.value + " cleared (will use generic terms)");
    } else {
      setExecBriefTerms(sel.value, terms);
      showToast("✅ Saved key terms for " + sel.value);
    }
    closeDialog();
  };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var showExecutiveBriefApp      = window.showExecutiveBriefApp;
  var showExecutiveBriefSettings = window.showExecutiveBriefSettings;
  if (!showExecutiveBriefApp) {
    eli.log.event("tool", "final_review_load_failed", {});
    return;
  }

  // Prime the exec-brief key-term cache from IDB so `getExecBriefTerms`
  // returns real data the first time _ebBuildEmptyData / renderExecutiveBrief
  // calls it. Async load + sync read is the v2 contract.
  if (typeof window._ebEnsureExecBriefTermsLoaded === "function") {
    window._ebEnsureExecBriefTermsLoaded();
  }

  // ─── Tile + gear handlers ────────────────────────────────────────
  function _open() {
    if (!eli.ai || typeof eli.ai.hasApiKey !== "function" || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && typeof eli.settings.show === "function") eli.settings.show();
      return;
    }
    // 2026-05-18 v48: stat MOVED to tile-only wrapper below. _open is
    // also called by final_review:open, _restoreBrief (BOTH on payload
    // AND fallback branches), and the activity_restore handlers —
    // counting them all inflated the launch tally.
    try { showExecutiveBriefApp(); }
    catch (e) {
      eli.log.event("tool", "final_review_launch_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Final Review failed to open: " + (e.message || "unknown"), "err");
    }
  }
  function _openSettings() {
    if (typeof showExecutiveBriefSettings !== "function") {
      if (typeof showToast === "function") showToast("Settings view not loaded", "err");
      return;
    }
    try { showExecutiveBriefSettings(); }
    catch (e) {
      eli.log.event("tool", "final_review_settings_failed", { msg: e && e.message });
    }
  }

  // 2026-05-13 follow-up: rich restore for the brief-complete activity
  // entry. The post-AI complete in runExecutiveBrief.js emits payload
  // { data: <merged brief>, type: <agreement type> } with
  // restoreChannel = "activity_restore", restoreKey = "approval-brief".
  // This handler:
  //   1. Opens the wizard (showExecutiveBriefApp resets state +
  //      async-loads requesters before rendering — we wait for it).
  //   2. Rehydrates window._ebData / window._ebType /
  //      window._frDataGenerated from the activity payload.
  //   3. Calls _frSetStep(2) to jump straight to the Final Audit
  //      (results) step. With _frDataGenerated already true,
  //      _frSetStep skips the AI re-run.
  // Poll backstop covers the async storage.getAll in showExecutiveBriefApp;
  // gives up after ~1.5s rather than spinning forever if the wizard
  // never mounts (e.g., no #output element).
  function _restoreBrief(payload) {
    if (!payload || !payload.data) { _open(); return; }
    _open();
    var attempts = 0;
    function _tryHydrate() {
      attempts++;
      var wizardReady = typeof window._frSetStep === "function"
        && document.getElementById("output");
      if (!wizardReady) {
        if (attempts < 30) return setTimeout(_tryHydrate, 50);
        eli.log.event("tool", "final_review_restore_timeout", { attempts: attempts });
        return;
      }
      try {
        window._ebData = payload.data;
        window._ebType = payload.type || (payload.data && payload.data.type) || null;
        window._frDataGenerated = true;
        window._frSetStep(2);
        eli.log.event("tool", "final_review_restored", {
          type: window._ebType || null,
          commitments: (payload.data.commitments || []).length,
        });
      } catch (e) {
        eli.log.event("tool", "final_review_restore_failed", { msg: e && e.message });
      }
    }
    setTimeout(_tryHydrate, 50);
  }

  // 2026-05-18 v48: tile wrapper records ONCE per real tile click.
  function _openFromTile() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedFinalReview"); } catch (e) {}
    _open();
  }
  eli.register({
    tile: { app_final_review: _openFromTile, "executive-brief": _openFromTile },
    tile_settings: { app_final_review: _openSettings, "executive-brief": _openSettings },
    final_review: { open: _open, settings: _openSettings },
    // Two restore keys — "approval-brief" is what runExecutiveBrief.js
    // emits on AI completion (rich payload). "executive-brief" is the
    // legacy key from older versions where restore just re-opened the
    // empty wizard — keep it as a fallback for any old activity rows
    // still in IDB.
    activity_restore: {
      "approval-brief":  _restoreBrief,
      "executive-brief": _restoreBrief,
    },
  });

  // ─── v2 globals → v3 provider bridges ────────────────────────────

  // `_ebEsc` and `tryParseGeminiJSON` shims removed 2026-05-12: both
  // now live in tools/final_review/_ebHelpers.js as tool-owned
  // helpers (`_ebEsc` + `_ebParseAiJson`), exposed by the bundler as
  // window globals to the other final_review files.

  // v2 `getAgreementTypes()` lives in legal_review's bundle-isolated
  // engine. final_review's v2 files call it as a global. Inline the
  // same list verbatim — adding 23 strings to keep the v2 files'
  // direct global call working unchanged.
  if (typeof window.getAgreementTypes !== "function") {
    window.getAgreementTypes = function () {
      return [
        "Amendment",
        "Clinical Study Agreement",
        "Consulting Agreement",
        "Consumer Study Agreement",
        "Grant Agreement",
        "Joint Development Agreement",
        "Letter",
        "Letter of Intent",
        "License Agreement",
        "Master Services Agreement",
        "Material Transfer Agreement",
        "Memorandum of Understanding",
        "Non-Disclosure Agreement",
        "Renewal",
        "Research Agreement",
        "Service Agreement",
        "Speaker Agreement",
        "Sponsorship Agreement",
        "Statement of Work",
        "Term Sheet",
        "Termination",
        "Visitor Agreement",
        "Other",
      ];
    };
  }

  // `callGemini` / `API_KEY` shims now live in the kernel — no need to
  // duplicate per-tool. (Was a race-condition vector when multiple v2-
  // style tools each tried to shim on first init.)

  // 2026-05-13 v2-compat: `formatPrompt(key, params, fallback)` and
  // `getPrompt(key, fallback)`. The kernel exposes only
  // `eli.ai.formatPrompt(template, params)` — string substitution, no
  // IDB key lookup. The v2 surface (key + IDB lookup + fallback) is
  // installed on demand by the FIRST consuming tool. Compare also
  // installs the same pair; if it loaded first, the typeof guards
  // below skip our install (single source on window). When neither
  // tool has loaded, runExecutiveBrief / _ebCards would throw
  // ReferenceError on bare `formatPrompt(...)` calls — that was the
  // "formatPrompt is not defined" final_review crash 2026-05-13.
  if (typeof window.formatPrompt !== "function" || typeof window.getPrompt !== "function") {
    var _frPromptCache = null;
    var _frPromptCacheLoading = null;
    function _frLoadPromptCache() {
      if (_frPromptCache) return Promise.resolve(_frPromptCache);
      if (_frPromptCacheLoading) return _frPromptCacheLoading;
      if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve({});
      _frPromptCacheLoading = eli.storage.getAll("prompts").then(function (rows) {
        var map = {};
        (rows || []).forEach(function (r) {
          if (r && r.id && typeof r.text === "string") map[r.id] = r.text;
        });
        _frPromptCache = map;
        _frPromptCacheLoading = null;
        return map;
      }).catch(function () { _frPromptCacheLoading = null; return {}; });
      return _frPromptCacheLoading;
    }
    _frLoadPromptCache();
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("data:installed", function (payload) {
        if (!payload || !payload.id || /prompts/i.test(payload.id)) _frPromptCache = null;
        _frLoadPromptCache();
      });
    }
    if (typeof window.getPrompt !== "function") {
      window.getPrompt = function (key, fallback) {
        if (!_frPromptCache && !_frPromptCacheLoading) _frLoadPromptCache();
        return (_frPromptCache || {})[key] || fallback || "";
      };
    }
    if (typeof window.formatPrompt !== "function") {
      window.formatPrompt = function (key, params, fallback) {
        var tpl = window.getPrompt(key, fallback);
        if (!tpl) return "";
        params = params || {};
        return tpl.replace(/\{\{(\w+)\}\}/g, function (_, name) {
          return params[name] != null ? String(params[name]) : "";
        });
      };
    }
  }

  // loadFeatureData + saveFeatureData + recordEliStat shims removed
  // 2026-05-12 — call sites use eli.storage / eli.stats directly.
  if (typeof window.setLoading !== "function") {
    window.setLoading = function () { /* no-op — kernel covers loading via FSM */ };
  }
  if (typeof window.handleError !== "function") {
    window.handleError = function (err) {
      eli.log.event("tool", "final_review_runtime_error", { msg: err && err.message });
      if (typeof showToast === "function") showToast("Error: " + (err && err.message || "unknown"), "err");
    };
  }

  // STORE_REQUESTERS is a string in the kernel ("requesters"); legal_review
  // and final_review reference it directly. Make sure it's window-accessible.
  if (typeof window.STORE_REQUESTERS === "undefined") {
    try { window.STORE_REQUESTERS = "requesters"; } catch (e) {}
  }

  // 2026-05-13 follow-up: dropped the open-time activity entry. It
  // was a payloadless "Opened wizard" record whose restore just
  // re-opened an empty wizard — NOT a useful session restore. The
  // meaningful entry is added on BRIEF COMPLETE (runExecutiveBrief.js)
  // which now carries restoreChannel + restoreKey + the full {data,
  // type} payload. Restore handler below rehydrates window._ebData /
  // window._ebType / window._frDataGenerated and jumps the wizard
  // straight to step 2 (Final Audit / results). Same pattern as
  // review_redlines' scan-complete restore.

  eli.log.event("tool", "final_review_initialized", {});
}
